mapper.update:
update assignment_info
title = #{title}, content = #{content}, course_id = #{courseId}, teacher_id = #{teacherId}, publish_time = #{publishTime}, due_time = #{dueTime}, attachment_path = #{attachmentPath},
where id = #{id}

mapper.select:
select ,
c.name as courseName, t.name as teacherName
from assignment_info ai
left join course c on ai.course_id = c.id
left join teacher t on ai.teacher_id = t.id

    and ai.id = #{id}
    and ai.title like concat('%', #{title}, '%')
    and ai.course_id = #{courseId}
    and ai.teacher_id = #{teacherId}

order by ai.publish_time desc, ai.id desc
